app.get('/products', (req, res) => {
  let list = products;
  if (req.query.q) {
    const q = req.query.q.toLowerCase();
    list = list.filter((p) => p.name.toLowerCase().includes(q));
  }
  if (req.query.max) {
    list = list.filter((p) => p.price <= Number(req.query.max));
  }
  res.json(list);
});
